import os
import re

# Load all grid data from this instance
def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    demo_num = [0]

    def parse_grids(text, num_cols):
        nonlocal demo_num
        grids = []
        for line in text.strip().split('\n'):
            if line.strip() == '':
                continue
            try:
                grids.append([[int(x) for x in line.split()] for x in line.split('\n')])
                break
            except:
                pass
        return grids

    # Try matching grid data
    for line in t.split('\n'):
        if re.match(r'Demo pair \d+ (?:input|output)', line):
            rows_txt = line.strip()
            # Find content after the marker
            idx = rows_txt.rfind(':')
            if idx >= 0:
                content = rows_txt[idx+1:].strip()
                lines = content.split('\n')
                rows = []
                grids = []
                for l in lines:
                    if l.strip() == '':
                        continue
                    try:
                        row = [int(x) for x in l.split()]
                        rows.append(row)
                        if len(rows) >= 10:  # 10x10 for this task
                            grids.append([x for x in rows])
                            break
                    except:
                        pass
                if grids:
                    demo_num[0] += 1
                    if len(rows) == 10:
                        G[f"Demo pair {demo_num[0]} input (10x10)"] = rows
    return G

G = load()
print("Loaded pairs:", list(G.keys()))
print("\n--- Test Input ---")
print(G.get('Test input (10x10)'))

